head.script:
scwin.init = function() {
    widgetContainer.addWidgets([{
            id: "widget1",
            title: "위젯1",
            src: "widgetContainer_Resize_WPF-1560_(WSQ-2560)_content.xml",
            scope: true,
            x: 0,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget2",
            title: "위젯2",
            src: "widgetContainer_Resize_WPF-1560_(WSQ-2560)_content.xml",
            scope: true,
            x: 1,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget3",
            title: "위젯3",
            src: "widgetContainer_Resize_WPF-1560_(WSQ-2560)_content.xml",
            scope: true,
            hasTitleBar: true,
            x: 2,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        }
    ]);
}
scwin.trigger1_onclick = function(e) {
    widgetContainer.enableWidgetResize(false);
};
scwin.trigger2_onclick = function(e) {
    widgetContainer.getWidgetById('widget2').setResizable(false);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
